    28	const ColorPicker = ({ value, onChange, disabled }: ColorPickerProps) => {
    29	  const [isOpen, setIsOpen] = useState(false);
    30	  const dropdownRef = useRef<HTMLDivElement>(null);
    31	
    32	  useEffect(() => {
    33	    const handleClickOutside = (event: MouseEvent) => {
    34	      if (
    35	        dropdownRef.current &&
    36	        !dropdownRef.current.contains(event.target as Node)
    37	      ) {
    38	        setIsOpen(false);
    39	      }
    40	    };
    41	
    42	    if (isOpen) {
    43	      document.addEventListener("mousedown", handleClickOutside);
    44	      return () => {
    45	        document.removeEventListener("mousedown", handleClickOutside);
    46	      };
    47	    }
    48	  }, [isOpen]);
    49	
    50	  const currentColor = value as TldrawColorName;
    51	  const bgColor = COLOR_PALETTE[currentColor] ?? COLOR_PALETTE.black;
    52	  const textColor = getContrastColor(bgColor ?? DEFAULT_TLDRAW_COLOR);
    53	
    54	  return (
    55	    <div ref={dropdownRef} className="relative min-w-32">
    56	      <button
    57	        type="button"
    58	        onClick={() => !disabled && setIsOpen(!isOpen)}
    59	        className="flex w-full items-center justify-between rounded border px-3 py-2 text-left"
    60	        style={{ backgroundColor: bgColor, color: textColor }}
    61	        disabled={disabled}
    62	      >
    63	        <span className="flex items-center gap-2">
    64	          <span
    65	            className="inline-block h-3 w-3 rounded-full border-2 border-solid"
    66	            style={{ backgroundColor: bgColor, border: `${textColor}` }}
    67	          />
    68	          {TLDRAW_COLOR_LABELS[currentColor]}
    69	        </span>
    70	        <span className="text-sm">{isOpen ? "▲" : "▼"}</span>
    71	      </button>
    72	
    73	      {isOpen && (
    74	        <div className="absolute z-50 mt-1 max-h-40 w-full overflow-y-auto">
    75	          {TLDRAW_COLOR_NAMES.map((colorName) => {
    76	            const bgColor = COLOR_PALETTE[colorName] ?? COLOR_PALETTE.black;
    77	            return (
    78	              <button
    79	                key={colorName}
    80	                type="button"
    81	                onClick={() => {
    82	                  onChange(colorName);
    83	                  setIsOpen(false);
    84	                }}
    85	                className="flex w-full flex-row justify-start gap-2 rounded-none px-3 py-2"
    86	              >
    87	                <span
    88	                  className="inline-block h-3 w-3 rounded-full"
    89	                  style={{ backgroundColor: bgColor }}
    90	                />
    91	                {TLDRAW_COLOR_LABELS[colorName]}
    92	              </button>
    93	            );
    94	          })}
    95	        </div>
