   101	const RelationshipTypeSettings = () => {
   102	  const plugin = usePlugin();
   103	  const [relationTypes, setRelationTypes] = useState<DiscourseRelationType[]>(
   104	    () => plugin.settings.relationTypes ?? [],
   105	  );
   106	  const [errors, setErrors] = useState<Record<number, string>>({});
   107	  // Ref to always have the latest state for onBlur handlers
   108	  // Updated in handleRelationTypeChange, not on render, to avoid stale reads
   109	  const relationTypesRef = useRef(relationTypes);
   110	
   111	  type EditableFieldKey = keyof Omit<
   112	    DiscourseRelationType,
   113	    "id" | "modified" | "created" | "importedFromRid" | "status"
   114	  >;
   115	
   116	  const saveSettings = (updatedRelationTypes: DiscourseRelationType[]) => {
   117	    const newErrors: Record<number, string> = {};
   118	
   119	    // Validate only complete types (ones with all required fields)
   120	    const completeTypes = updatedRelationTypes.filter(
   121	      (rt) => rt.id && rt.label && rt.complement,
   122	    );
   123	
   124	    // Check for duplicate labels
   125	    const seenLabels = new Map<string, number>();
   126	    for (const rt of completeTypes) {
   127	      const idx = updatedRelationTypes.indexOf(rt);
   128	      const prev = seenLabels.get(rt.label);
   129	      if (prev !== undefined) {
   130	        newErrors[idx] = `Duplicate label "${rt.label}"`;
   131	        if (!newErrors[prev]) newErrors[prev] = `Duplicate label "${rt.label}"`;
   132	      }
   133	      seenLabels.set(rt.label, idx);
   134	    }
   135	
   136	    // Check for duplicate complements
   137	    const seenComplements = new Map<string, number>();
   138	    for (const rt of completeTypes) {
   139	      const idx = updatedRelationTypes.indexOf(rt);
   140	      const prev = seenComplements.get(rt.complement);
   141	      if (prev !== undefined) {
   142	        newErrors[idx] = `Duplicate complement "${rt.complement}"`;
   143	        if (!newErrors[prev])
   144	          newErrors[prev] = `Duplicate complement "${rt.complement}"`;
   145	      }
   146	      seenComplements.set(rt.complement, idx);
   147	    }
   148	
   149	    setErrors(newErrors);
   150	    if (Object.keys(newErrors).length > 0) return;
   151	
   152	    // Only persist complete local types + all imported types
   153	    const importedTypes = updatedRelationTypes.filter(
   154	      (rt) => rt.importedFromRid,
   155	    );
   156	    plugin.settings.relationTypes = [
   157	      ...completeTypes.filter((rt) => !rt.importedFromRid),
   158	      ...importedTypes,
   159	    ];
   160	    void plugin.saveSettings();
   161	  };
   162	
   163	  const handleRelationTypeChange = (
   164	    index: number,
   165	    field: EditableFieldKey,
   166	    value: string,
   167	  ): void => {
   168	    const now = new Date().getTime();
   169	    const updatedRelationTypes = [...relationTypes];
   170	    if (!updatedRelationTypes[index]) {
   171	      const newId = generateUid("rel");
   172	      updatedRelationTypes[index] = {
   173	        id: newId,
   174	        label: "",
   175	        complement: "",
   176	        color: DEFAULT_TLDRAW_COLOR,
   177	        created: now,
   178	        modified: now,
   179	      };
   180	    }
   181	    const updated = {
   182	      ...updatedRelationTypes[index],
   183	      modified: now,
   184	      ...(field === "color"
   185	        ? { color: value as TldrawColorName }
   186	        : { [field]: value }),
   187	    };
   188	    updatedRelationTypes[index] = updated;
   189	    setRelationTypes(updatedRelationTypes);
   190	    relationTypesRef.current = updatedRelationTypes;
   191	    if (field === "color") {
   192	      // Color is a discrete input — save immediately
   193	      saveSettings(updatedRelationTypes);
   194	    }
   195	  };
   196	
   197	  const handleAddRelationType = (): void => {
   198	    const newId = generateUid("rel");
   199	    const now = new Date().getTime();
   200	
   201	    const updatedRelationTypes = [
   202	      ...relationTypes,
   203	      {
   204	        id: newId,
   205	        label: "",
   206	        complement: "",
   207	        color: DEFAULT_TLDRAW_COLOR,
   208	        created: now,
   209	        modified: now,
   210	      },
   211	    ];
   212	    setRelationTypes(updatedRelationTypes);
   213	  };
   214	
   215	  const confirmDeleteRelationType = (index: number): void => {
   216	    const relationType = relationTypes[index] || {
   217	      label: "Unnamed",
   218	      complement: "",
   219	      color: DEFAULT_TLDRAW_COLOR,
   220	    };
   221	    const modal = new ConfirmationModal(plugin.app, {
   222	      title: "Delete relation type",
   223	      message: `Are you sure you want to delete the relation type "${relationType.label}"?`,
   224	      onConfirm: () => {
   225	        void handleDeleteRelationType(index);
   226	      },
   227	    });
   228	    modal.open();
   229	  };
   230	
   231	  const handleDeleteRelationType = async (index: number): Promise<void> => {
   232	    const isUsed = plugin.settings.discourseRelations?.some(
   233	      (rel) => rel.relationshipTypeId === relationTypes[index]?.id,
   234	    );
   235	
   236	    if (isUsed) {
   237	      new Notice(
   238	        "Cannot delete this relation type as it is used in one or more relations.",
   239	      );
   240	      return;
   241	    }
   242	
   243	    const updatedRelationTypes = relationTypes.filter((_, i) => i !== index);
   244	    setRelationTypes(updatedRelationTypes);
   245	    plugin.settings.relationTypes = updatedRelationTypes;
   246	    await plugin.saveSettings();
   247	    new Notice("Relation type deleted successfully");
   248	  };
   249	
   250	  const handleAcceptRelationType = async (index: number): Promise<void> => {
   251	    const updatedRelationTypes = [...relationTypes];
   252	    const relType = updatedRelationTypes[index];
   253	    if (!relType) return;
   254	    updatedRelationTypes[index] = { ...relType, status: "accepted" };
   255	    setRelationTypes(updatedRelationTypes);
   256	    plugin.settings.relationTypes = updatedRelationTypes;
   257	    await plugin.saveSettings();
   258	  };
   259	
   260	  const localRelationTypes = relationTypes.filter(
   261	    (relationType) => !relationType.importedFromRid,
   262	  );
   263	  const importedRelationTypes = relationTypes.filter(
   264	    (relationType) => relationType.importedFromRid,
   265	  );
   266	
   267	  const renderRelationTypeItem = (
   268	    relationType: DiscourseRelationType,
   269	    index: number,
   270	  ) => {
   271	    const importInfo = getImportInfo(relationType.importedFromRid);
   272	    const isImported = importInfo.isImported;
   273	    const isProvisional = isProvisionalSchema(relationType);
   274	    const spaceName = importInfo.spaceUri
   275	      ? formatImportSource(importInfo.spaceUri, plugin.settings.spaceNames)
   276	      : "imported space";
   277	
   278	    const error = errors[index];
   279	
   280	    return (
   281	      <div key={index} className="setting-item">
   282	        <div className="flex min-w-0 flex-1 flex-col gap-1">
   283	          <div className="flex flex-wrap items-center gap-2">
   284	            <input
   285	              type="text"
   286	              placeholder="Label (e.g., supports)"
   287	              value={relationType.label}
   288	              onChange={(e) =>
   289	                handleRelationTypeChange(index, "label", e.target.value)
   290	              }
   291	              onBlur={() => saveSettings(relationTypesRef.current)}
   292	              className={`min-w-32 flex-1 ${error ? "input-error" : ""}`}
   293	              disabled={isImported}
   294	            />
   295	            <input
   296	              type="text"
   297	              placeholder="Complement (e.g., is supported by)"
   298	              value={relationType.complement}
   299	              onChange={(e) =>
   300	                handleRelationTypeChange(index, "complement", e.target.value)
   301	              }
   302	              onBlur={() => saveSettings(relationTypesRef.current)}
   303	              className={`min-w-48 flex-[2] ${error ? "input-error" : ""}`}
   304	              disabled={isImported}
   305	            />
   306	            <ColorPicker
   307	              value={relationType.color}
   308	              onChange={(color) =>
   309	                handleRelationTypeChange(index, "color", color)
   310	              }
   311	              disabled={isImported}
   312	            />
   313	            <div className="flex shrink-0 gap-2">
   314	              {isImported && isProvisional && (
   315	                <button
   316	                  onClick={() => void handleAcceptRelationType(index)}
   317	                  className="p-2"
   318	                  title={`Accept this relation type from ${spaceName} to create relations of this type`}
   319	                >
   320	                  Accept
   321	                </button>
   322	              )}
   323	              <button
   324	                onClick={() => confirmDeleteRelationType(index)}
   325	                className="mod-warning p-2"
   326	              >
   327	                Delete
   328	              </button>
   329	            </div>
   330	          </div>
   331	          {error && <div className="text-error text-xs">{error}</div>}
   332	          {isImported && (
   333	            <ImportedSchemaMeta
   334	              isProvisional={isProvisional}
   335	              spaceUri={importInfo.spaceUri}
   336	              authorId={relationType.authorId}
   337	            />
   338	          )}
   339	        </div>
   340	      </div>
   341	    );
   342	  };
   343	
   344	  return (
   345	    <div className="discourse-relation-types">
   346	      {localRelationTypes.length > 0 && (
   347	        <div>
   348	          <h4 className="text-muted mb-2 text-sm font-semibold uppercase tracking-wide">
   349	            Local
   350	          </h4>
   351	          {localRelationTypes.map((relationType) => {
   352	            const index = relationTypes.indexOf(relationType);
   353	            return renderRelationTypeItem(relationType, index);
   354	          })}
   355	        </div>
   356	      )}
   357	
   358	      {importedRelationTypes.length > 0 && (
   359	        <div className="border-modifier-border mt-6 border-t pt-4">
   360	          <h4 className="text-muted mb-2 text-sm font-semibold uppercase tracking-wide">
   361	            Imported
   362	          </h4>
   363	          {importedRelationTypes.map((relationType) => {
   364	            const index = relationTypes.indexOf(relationType);
   365	            return renderRelationTypeItem(relationType, index);
   366	          })}
   367	        </div>
   368	      )}
   369	
   370	      <div className="mt-4 flex gap-2">
   371	        <button onClick={handleAddRelationType} className="p-2">
   372	          Add relation type
   373	        </button>
   374	      </div>
   375	    </div>
   376	  );
   377	};
   378	
   379	export default RelationshipTypeSettings;
